create or replace function public.seed_owner_platform_admin() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if lower(new.email) = 'baalhassane522@gmail.com' then
    insert into public.platform_admins (user_id, email, role, status)
    values (new.id, lower(new.email), 'super_admin', 'active')
    on conflict (user_id) do update set email = excluded.email, role = 'super_admin', status = 'active';
  end if;
  return new;
end;
$$;

drop trigger if exists on_auth_user_seed_platform_admin on auth.users;
create trigger on_auth_user_seed_platform_admin
  after insert on auth.users
  for each row execute function public.seed_owner_platform_admin();
